// the synthesized audio).
const FILIPINO_LETTER_NAMES = {
  A: "ey", B: "bi", C: "si", D: "di", E: "i", F: "ef", G: "dyi", H: "eych", I: "ay",
  J: "dyey", K: "key", L: "el", M: "em", N: "en", O: "o", P: "pi", Q: "kyu", R: "ar",
  S: "es", T: "ti", U: "yu", V: "vi", W: "dobolyu", X: "eks", Y: "way", Z: "zi",
};
